def fill_box_rings(grid, box_color=5, pattern=(5, 2, 5, 0)):
    """Fill the interior of a rectangular box of box_color with concentric square rings cycling through pattern (counted from the border); a leftover core of size <= 2 is painted with the next pattern color, a larger leftover core is left unchanged; an already-painted box is returned unchanged."""
    g=[row[:] for row in grid]
    rows=[i for i,r in enumerate(g) if box_color in r]
    cols=[j for r in g for j,c in enumerate(r) if c==box_color]
    if not rows: return g
    top,bot,left,right=min(rows),max(rows),min(cols),max(cols)
    size=right-left+1
    if any(g[i][j] not in (0,box_color) for i in range(top+1,bot) for j in range(left+1,right)):
        return g
    k=0
    while size-2*k>=3:
        c=pattern[k%len(pattern)]
        for j in range(left+k,right-k+1):
            g[top+k][j]=c; g[bot-k][j]=c
        for i in range(top+k+1,bot-k):
            g[i][left+k]=c; g[i][right-k]=c
        k+=1
    if 0<size-2*k<=2:
        c=pattern[k%len(pattern)]
        for i in range(top+k,bot-k+1):
            for j in range(left+k,right-k+1):
                g[i][j]=c
    return g

